package structural.decorator.sample;

// Wraps a Coffee and satisfies the same interface — decorators can be stacked.
public abstract class CoffeeDecorator implements ICoffee {
    protected final ICoffee coffee;

    protected CoffeeDecorator(ICoffee coffee) {
        this.coffee = coffee;
    }
}

package structural.decorator.sample.CoffeeDecorators;

import structural.decorator.sample.CoffeeDecorator;
import structural.decorator.sample.ICoffee;

public class CaramelDecorator extends CoffeeDecorator {
    public CaramelDecorator(ICoffee coffee) {
        super(coffee);
    }

    @Override
    public String description() {
        return this.coffee.description() + " + Caramel";
    }

    @Override
    public double cost() {
        return this.coffee.cost() + 15;
    }
}

package structural.decorator.sample.CoffeeDecorators;

import structural.decorator.sample.CoffeeDecorator;
import structural.decorator.sample.ICoffee;

public class MilkDecorator extends CoffeeDecorator {
    public MilkDecorator(ICoffee coffee) {
        super(coffee);
    }

    @Override
    public String description() {
        return this.coffee.description() + " + Milk";
    }

    @Override
    public double cost() {
        return this.coffee.cost() + 10;
    }
}

package structural.decorator.sample;

public interface ICoffee {
    String description();
    double cost();
}

package structural.decorator.sample;

import structural.decorator.sample.CoffeeDecorators.CaramelDecorator;
import structural.decorator.sample.CoffeeDecorators.MilkDecorator;

public class Main {
    public static void main(String[] args) {
        ICoffee coffee = new SimpleCoffee();
        System.out.println(coffee.description() + " -> " + coffee.cost());

        ICoffee milkCoffee = new MilkDecorator(coffee);
        System.out.println(milkCoffee.description() + " -> " + milkCoffee.cost());

        ICoffee caramelCoffee = new CaramelDecorator(coffee);
        System.out.println(caramelCoffee.description() + " -> " + caramelCoffee.cost());

        ICoffee milkCaramelCoffee = new CaramelDecorator(milkCoffee);
        System.out.println(milkCaramelCoffee.description() + " -> " + milkCaramelCoffee.cost());
    }
}

package structural.decorator.sample;

public class SimpleCoffee implements ICoffee {
    @Override
    public String description() {
        return "Coffee";
    }

    @Override
    public double cost() {
        return 50;
    }
}

